/bin/zsh -lc "ls -lh nd-unfolding/g2_fullevent/input/G2_FPS_MEFHC_P12.npz nd-unfolding/g2_fullevent/gate2/final 2>/dev/null || true; python3 - <<'PY'
import json, os, glob
for p in glob.glob('nd-unfolding/g2_fullevent/gate2/final/*.json'):
    print(p)
    d=json.load(open(p))
    print('top',sorted(d)[:30])
    for k in ('status','verdict','runtime_target','step1_feed','input_preflight','configuration'):
        if k in d: print(k, d[k] if k in ('status','verdict') else str(d[k])[:1200])
PY
rg -n 'G2_GATE2|weights|G2_FPS_MEFHC_P12' nd-unfolding/g2_fullevent/gate2/final docs/orchestration/state/g2-gate2* nd-unfolding/pet/sbatch_pet_fullevent_nominal.sh nd-unfolding/pet/train_fullevent_nominal.py | sed -n '1,320p'"

